/* 자동 생성 파일. 직접 고치지 말고 data/ 의 JSON을 고친 뒤 python tools/build_data.py 를 실행한다. */
window.TRACK_DATA={"tracks":{"version":"0.1","updated":"2026-10-05","note":"첫 화면의 '어디에 + 무엇을' 선택지. ready가 true인 트랙만 data/tracks/<id>/ 의 규칙 데이터를 읽는다.","where":[{"id":"KR","label":"한국"},{"id":"CN","label":"중국"}],"tracks":[{"id":"KR-JSC","where":"KR","label":"주식회사","ready":true,"note":"외국 투자자의 한국 주식회사 설립. 선례 3건과 표준키트를 근거로 합니다."},{"id":"KR-LLC","where":"KR","label":"유한회사","ready":false,"note":"한국 유한회사 트랙은 규칙 자료가 아직 없습니다."},{"id":"KR-BR","where":"KR","label":"지점","ready":false,"note":"한국 지점 트랙은 규칙 자료가 아직 없습니다."},{"id":"KR-LO","where":"KR","label":"연락사무소","ready":false,"note":"한국 연락사무소 트랙은 규칙 자료가 아직 없습니다."},{"id":"CN-WFOE","where":"CN","label":"독자법인","ready":false,"note":"중국 독자법인 트랙은 선례 1건(상하이 린강)의 절차와 입력 항목을 정리한 단계입니다. 데이터 파일로 옮긴 뒤 열립니다."},{"id":"CN-JV","where":"CN","label":"합자법인","ready":false,"note":"중국 합자법인 트랙은 선례 자료가 없습니다."},{"id":"CN-RO","where":"CN","label":"대표처","ready":false,"note":"중국 대표처 트랙은 선례 1건(동관)의 필요서류를 정리한 단계입니다. 데이터 파일로 옮긴 뒤 열립니다."},{"id":"CN-BRANCH","where":"CN","label":"분공사","ready":false,"note":"중국 분공사 트랙은 선례 자료가 없습니다."}]},"data":{"KR-JSC":{"inputs":{"track":"KR-JSC","title":"외국 투자자의 한국 주식회사 설립","version":"0.2","updated":"2026-10-05","source":"한국법인 설립 표준키트 v0.7 (2026-09-28)","note":"1층 입력: 분기를 결정하는 항목만. 개인정보 없음. 2층(문서 생성용 상세 항목)은 필드사전을 옮길 때 추가한다. import_key와 alias는 docgen.py read 결과(program_inputs)의 짧은 키·값을 이 파일의 키·값으로 바꾸는 데 쓴다. screen이 false인 항목은 화면에 표시하지 않는다.","inputs":[{"key":"shareholder_type","import_key":"sh","label":"출자 주체(주주) 유형","type":"select","required":true,"options":[{"value":"cn_company_direct","label":"중국 법인(본사 직접 출자)","alias":["cn"]},{"value":"offshore_holding","label":"해외 지주사(싱가포르·홍콩 등)","alias":["hold"]},{"value":"tax_haven_company","label":"조세회피지 법인(케이만 등)","alias":["haven"]},{"value":"foreign_individual","label":"외국 개인","alias":["indiv"]}],"rules":["R01","R02","R03","R04"]},{"key":"capital_krw","import_key":"cap","label":"자본금(원)","type":"number","required":true,"default":100000000,"rules":["R05","R06","R07","R08"],"hint":"1억 원과 10억 원이 분기 기준"},{"key":"ownership_pct","import_key":"own","label":"외국 투자자 지분율(%)","type":"number","required":true,"default":100,"rules":["R05"]},{"key":"director_count","import_key":"dir","label":"이사 수","type":"select","required":true,"options":[{"value":"1","label":"1인"},{"value":"2","label":"2인"},{"value":"3plus","label":"3인 이상"}],"rules":["R07","R08","R15"],"warn_if":"capital_krw >= 1000000000 && director_count != '3plus'","warn_text":"자본금 10억 원 이상이면 이사 3인 이상이 필요합니다."},{"key":"has_auditor","import_key":"aud","label":"감사 선임 여부","type":"boolean","required":true,"options":[{"value":false,"label":"두지 않음"},{"value":true,"label":"둠"}],"rules":["R07","R08"],"warn_if":"capital_krw >= 1000000000 && has_auditor == false","warn_text":"자본금 10억 원 이상이면 감사가 필수입니다."},{"key":"officers_location","import_key":"loc","label":"임원 서명 장소","type":"select","required":true,"options":[{"value":"abroad","label":"해외 거주(현지 서명)"},{"value":"visit_korea","label":"한국 체류 중 율촌 방문 서명","alias":["visit"]}],"rules":["R09","R10"]},{"key":"rep_director_residence","import_key":"res","label":"대표이사 거주지·신분증","type":"select","required":true,"options":[{"value":"cn_mainland","label":"중국 대륙 거주(거민신분증에 주소 있음)","alias":["cn"]},{"value":"other_or_no_address","label":"홍콩·마카오·기타 외국 또는 신분증에 주소 없음","alias":["other"]}],"rules":["R16"],"hint":"대표이사 주소는 등기사항. 늦게 확인하면 공증에 수주가 걸릴 수 있어 첫 단계에서 확인"},{"key":"head_office_zone","import_key":"zone","label":"본점 소재지 권역","type":"select","required":true,"options":[{"value":"overcrowding","label":"과밀억제권역(서울 등, 산업단지 제외)","alias":["over"]},{"value":"other","label":"그 외 지역 또는 산업단지"}],"rules":["R11"]},{"key":"office_type","import_key":"off","label":"사무실 형태","type":"select","required":true,"options":[{"value":"independent","label":"독립 사무실","alias":["indep"]},{"value":"virtual_shared","label":"비상주·공유오피스","alias":["virtual"]}],"rules":["R12"]},{"key":"restricted_business","import_key":"biz","label":"사업목적에 외국인투자 제한 업종 또는 인허가 업종 포함","type":"select","required":true,"default":"unknown","options":[{"value":"yes","label":"포함"},{"value":"no","label":"없음"},{"value":"unknown","label":"아직 모름"}],"rules":["R13","R19"]},{"key":"d8_needed","import_key":"d8","label":"파견 임원의 D-8 비자 필요","type":"boolean","required":true,"options":[{"value":false,"label":"필요 없음"},{"value":true,"label":"필요함"}],"rules":["R14"]},{"key":"pre_registration_cost_method","label":"등기 전 비용 지급 방식","type":"select","required":false,"default":"undecided","options":[{"value":"yulchon_advance","label":"율촌 대납(소액만)"},{"value":"client_remit","label":"고객 선송금"},{"value":"korean_affiliate","label":"한국 관계사 지급"},{"value":"undecided","label":"미정"}],"rules":["R17"]},{"key":"preferred_bank","label":"고객 선호 은행","type":"text","required":false,"rules":["R20"],"hint":"고객 요청서에는 은행명을 먼저 제시하지 않고 선호 유무만 질문"},{"key":"output_language","label":"고객용 출력 언어","type":"select","required":true,"default":"zh","screen":false,"options":[{"value":"ko","label":"한국어"},{"value":"zh","label":"중국어"},{"value":"en","label":"영어"}]}],"derived":[{"key":"is_foreign_company_shareholder","expr":"shareholder_type in ['cn_company_direct','offshore_holding','tax_haven_company']"},{"key":"is_fdi","expr":"capital_krw >= 100000000 && ownership_pct >= 10","label":"외국인투자촉진법상 외국인투자 해당"},{"key":"capital_tier","expr":"capital_krw >= 1000000000 ? 'gte_1bn' : 'lt_1bn'"},{"key":"needs_cn_odi","expr":"shareholder_type == 'cn_company_direct'"}],"warnings":[{"when":"d8_needed == true && office_type == 'virtual_shared'","text":"D-8 비자에는 독립 사무실이 필요합니다. 비상주·공유오피스는 인정되지 않을 수 있습니다.","basis":"R14, R12"},{"when":"d8_needed == true && !is_fdi","text":"D-8 비자는 외국인투자기업 등록이 전제입니다. 자본금 1억 원 이상, 지분 10% 이상이어야 합니다.","basis":"R05, P12-3"},{"when":"capital_krw >= 100000000 && ownership_pct < 10","text":"지분 10% 미만이면 외국인투자촉진법상 외국인투자에 해당하지 않습니다.","basis":"R05"}]},"rules":{"track":"KR-JSC","version":"0.1","updated":"2026-10-05","source":"한국법인 설립 표준키트 v0.7 분기규칙·확인필요 시트","status_values":{"confirmed":"법령 또는 선례·법무지원팀 확인 완료","pilot":"내부 확인은 됐으나 첫 사건(선례 C) 진행 중이라 결과 반영 예정","needs_check":"확인필요. 화면에 단정하지 않고 표시만 한다","practice":"율촌 내부 업무 원칙(법령 아님)"},"rules":[{"id":"R01","topic":"주주 유형","when":"shareholder_type == 'cn_company_direct'","text":"중국 ODI 선행. 공증+아포스티유는 율촌 작성 서명서류(A1~A6)만. 영업집조·주주명부(실제소유자)·세무번호 증명·법정대표인 여권은 스캔본. 이사회결의·정관은 사본. 한국어 번역은 율촌(번역인 확인, 번역공증 불요).","effects":{"process_add":["P1-3","P6-1","P6-2","P6-3"],"documents":["A1","C1","C2","C3","C4","C5","C6","C7"]},"status":"pilot","basis":"법무지원팀 최종확인(2026-09-28). 선례 C가 첫 사례","region":"KR 전국 / CN 측은 지역별 확인필요"},{"id":"R02","topic":"주주 유형","when":"shareholder_type == 'offshore_holding'","text":"해당국 등록증명(예: 싱가포르 Bizfile). 실제소유자 확인(최대주주가 법인이면 그 주주명부 추가). 위임장 공증+아포스티유.","effects":{"documents":["A1","C2","C4"],"documents_extra":["해당국 등록증명","상위 주주명부(최대주주가 법인인 경우)"]},"status":"confirmed","basis":"선례 A(은행 서류목록)","region":"KR 전국"},{"id":"R03","topic":"주주 유형","when":"shareholder_type == 'tax_haven_company'","text":"R02에 더해 등록대리인 발급 재직증명 등 은행 KYC 강화에 대비.","effects":{"inherits":"R02","documents_extra":["등록대리인 발급 재직증명(Certificate of Incumbency)"],"flags":["bank_kyc_enhanced"]},"status":"confirmed","basis":"선례 B","region":"KR 전국"},{"id":"R04","topic":"주주 유형","when":"shareholder_type == 'foreign_individual'","text":"여권 사본(공증 불요) + 위임장 공증+아포스티유. 자금출처와 송금인 명의 일치 확인.","effects":{"documents":["A1"],"documents_extra":["주주 여권 사본"],"flags":["check_fund_source","remitter_name_match"]},"status":"confirmed","basis":"선례 D","region":"KR 전국"},{"id":"R05","topic":"투자 규모","when":"capital_krw >= 100000000 && ownership_pct >= 10","text":"외국인투자촉진법상 외국인투자에 해당. 외국인투자신고와 외국인투자기업 등록 필요. D-8 비자의 기반.","effects":{"process_add":["P8-1","P12-1"]},"status":"confirmed","basis":"외국인투자촉진법. 등록 기한은 시행령 제27조 제1항(납입 완료일부터 60일 이내)","region":"KR 전국"},{"id":"R06","topic":"투자 규모","when":"capital_krw < 100000000","text":"외국인투자촉진법상 외국인투자에 해당하지 않음. 외국환거래법상 절차는 별도 확인필요.","effects":{"process_skip":["P8-1","P12-1"],"flags":["fx_act_procedure_check"]},"status":"needs_check","basis":"문의 유형으로만 접수. 선례 없음","region":"KR 전국"},{"id":"R07","topic":"자본금","when":"capital_krw >= 1000000000","text":"이사 3인 이상·이사회·감사 필수. 주금납입보관증명서 필수. 정관과 의사록에 공증인 인증 필요.","effects":{"require":{"director_count":"3plus","has_auditor":true},"flags":["share_payment_custody_cert","notary_cert_articles_minutes"]},"status":"confirmed","basis":"상법. 법령 확인(2026-09-26)","region":"KR 전국"},{"id":"R08","topic":"자본금","when":"capital_krw < 1000000000","text":"이사 1~2인 가능(이사회 생략 가능). 감사 생략 가능. 잔고증명서로 주금납입보관증명서 대체 가능. 정관·의사록 공증인 인증 불요.","effects":{"flags":["balance_cert_ok","no_notary_cert_articles_minutes"]},"status":"confirmed","basis":"상법 제292조 단서, 공증인법 제66조의2 제1항 제1호","region":"KR 전국"},{"id":"R09","topic":"임원 소재","when":"officers_location == 'abroad'","text":"취임승낙서·인감신고서·위임장을 현지에서 공증+아포스티유. 주소 증명 첨부(R16 참조).","effects":{"process_add":["P4-2"],"documents":["A2","A3","A4","A5","A6"]},"status":"confirmed","basis":"선례 A","region":"KR 전국"},{"id":"R10","topic":"임원 소재","when":"officers_location == 'visit_korea'","text":"임원이 한국 체류 중 율촌을 방문해 서명하는 경우 해외 공증·아포스티유를 생략할 수 있는지는 확인필요(외국인등록증 보유 시).","effects":{"flags":["skip_overseas_notarization_check"]},"status":"needs_check","basis":"선례 D 회의에서 논의만 됨","region":"KR 전국"},{"id":"R11","topic":"본점 소재지","when":"head_office_zone == 'overcrowding'","text":"등록면허세 3배 중과(0.4% → 1.2%, 지방교육세 포함 약 1.44%). 설립 후 5년 내 증자, 권역 밖에서 5년 내 전입도 중과. 자료요청서 첨부 세액표로 안내. 예외: 중과 제외 업종(시행령 제26조).","effects":{"cost_multiplier":{"registration_tax":3}},"status":"confirmed","basis":"지방세법 제28조 제2항. 법령 확인(2026-09-27)","region":"과밀억제권역(산업단지 제외)"},{"id":"R12","topic":"본점 형태","when":"office_type == 'virtual_shared'","text":"고객에게 비권장으로 안내. 사업자등록 현장확인·보완·거부 가능, 법인계좌 심사 강화, D-8 독립 사무실 불인정(KOTRA IKP는 인정). 최소 계약기간과 호실 기재 확인.","effects":{"flags":["warn_virtual_office"]},"status":"needs_check","basis":"비상주 사무실로 외국인투자기업 사업자등록이 가능한지 최근 실무를 법무지원팀에 확인 중(Q01-D)","region":"KR 전국"},{"id":"R13","topic":"사업목적","when":"restricted_business in ['yes','unknown']","text":"외국인투자 비율 제한과 별도 인허가를 검토. 설립 직후 실제 사업 기준으로 사업목적을 최소화하도록 권고.","effects":{"process_emphasis":["P1-4"],"flags":["restricted_business_review"]},"status":"confirmed","basis":"실무 원칙","region":"KR 전국"},{"id":"R14","topic":"파견 임원","when":"d8_needed == true","text":"투자액·자금출처 증빙 요건을 별도 검토. 독립 사무실 필요.","effects":{"process_add":["P12-3"],"require":{"office_type":"independent"}},"status":"needs_check","basis":"세부 요건은 사건별 확인","region":"KR 전국"},{"id":"R15","topic":"이사 수","when":"always","text":"1인: 대표이사 없음, 사내이사가 회사를 대표, 서명서류 직함은 'Director', 본점은 이사 결정서로 정함. 2인: 각자 대표가 원칙, 대표이사를 두려면 정관에 근거 필요, 본점은 이사 결정서. 3인 이상: 이사회 의사록으로 대표이사 선임과 본점 결정.","effects":{"by_director_count":{"1":{"rep_title":"Director","head_office_decision":"이사 결정서","board":false},"2":{"rep_title":"정관에 따라","head_office_decision":"이사 결정서","board":false},"3plus":{"rep_title":"Representative Director","head_office_decision":"이사회 의사록","board":true}}},"status":"confirmed","basis":"상법 제383조 제6항. 선례 A의 이사 수는 확인필요","region":"KR 전국"},{"id":"R16","topic":"대표이사 주소","when":"always","text":"중국 대륙 거주자: 거민신분증 앞뒤면 사본(여권으로 대체 불가). 그 외(홍콩·마카오·외국인) 또는 신분증에 주소가 없는 경우: 공증+아포스티유 주소증명을 별도로 준비. 첫 자료요청서에서 조기 확보. 취임승낙서·인감신고서의 주소와 일치해야 함.","effects":{"by_rep_director_residence":{"cn_mainland":{"documents_extra":["거민신분증 앞뒤면 사본"]},"other_or_no_address":{"documents":["B1"],"flags":["address_proof_early"]}}},"status":"confirmed","basis":"과거 홍콩 건 경험","region":"KR 전국"},{"id":"R17","topic":"등기 전 비용","when":"always","text":"자본금은 등기와 법인계좌 개설 전에는 쓸 수 없음. 등록면허세·임대 계약금·보증금·실비의 지급 방식을 자료요청서에서 선택받음(율촌 대납은 소액만 / 고객 선송금 / 한국 관계사 지급).","effects":{"process_add":["P2-5"]},"status":"practice","basis":"과거 대납 경험","region":"KR 전국"},{"id":"R18","topic":"상호","when":"always","text":"한글 상호는 고객이 결정. 율촌은 중복 조회만 하고 추천하지 않음.","effects":{},"status":"practice","basis":"내부 원칙","region":"KR 전국"},{"id":"R19","topic":"사업목적 작성","when":"always","text":"고객이 원하는 목적을 먼저 작성하고 율촌이 사후 검토. 율촌이 예시나 추천을 먼저 제시하지 않음.","effects":{},"status":"practice","basis":"내부 원칙","region":"KR 전국"},{"id":"R20","topic":"은행","when":"always","text":"고객 요청서에는 은행명을 제시하지 않고 선호 은행 유무만 질문. 회신 후 결정.","effects":{},"status":"practice","basis":"내부 원칙","region":"KR 전국"},{"id":"R21","topic":"공증 시점","when":"always","text":"첫 자료요청서 단계에서는 스캔본만 받고 공증하지 말라고 안내. 서명서류 완성 후 서명·공증 안내서(待签署及公证文件清单)로 공증 대상과 부수를 한 번에 지시(재공증 방지).","effects":{"client_guide_dont":["서명서류를 받기 전에 미리 공증받지 마십시오."]},"status":"practice","basis":"과거 시행착오","region":"KR 전국"},{"id":"R22","topic":"번역","when":"always","text":"번역은 한국에서 율촌이 1회 수행(번역인 성명·주소·서명). 중국 공증처 번역과 한국 번역공증 모두 불요. 공증처가 요구하면 율촌이 중문 참고번역을 제공.","effects":{"client_guide_dont":["번역공증을 따로 받지 마십시오. 번역은 율촌이 한국에서 합니다."]},"status":"confirmed","basis":"상업등기선례 제1-22호","region":"KR 전국"}],"open_items":[{"id":"Q-A","text":"등기신청 대리권: 대표이사 위임장의 등기 신청 권한 조항으로 충분한지, 법인인감 날인 등기위임장이 따로 필요한지","owner":"법무지원","affects":"등기서류 세트"},{"id":"Q-D","text":"비상주 사무실 계약으로 외국인투자기업 사업자등록이 가능한지(최근 실무)","owner":"법무지원","affects":"R12"},{"id":"Q-E","text":"대표이사가 비거주 외국인일 때 사업자등록·계좌 개설에서 방한 또는 납세관리인 지정을 요구하는지","owner":"법무지원","affects":"R16, 일정"},{"id":"Q-G","text":"주주 위임장 원본 부수: 은행 제출 후 등기용이 남는지. 선례 A는 2부, 표준은 3부(은행 1, 등기 1, 예비 1)","owner":"법무지원","affects":"A1 부수"},{"id":"Q-N","text":"중국 공증처가 한/영 병기 서류를 중문 번역 없이 공증하는지(공증처마다 다를 수 있음). 대응: 율촌이 중문 참고번역 준비, 고객이 공증처에 사전 확인","owner":"고객 통해 확인","affects":"서명서류 언어 방식"},{"id":"Q-F","text":"자본금 1억 원 미만 외국인 출자 시 외국환거래법상 절차","owner":"변호사","affects":"R06"},{"id":"Q-O","text":"중국 ODI(발개위, 상무주관부문, 은행 외환등기) 소요기간","owner":"고객 통해 확인","affects":"P6, 송금 일정"},{"id":"Q-T","text":"법무지원팀·업무지원팀의 실제 업무범위(프로세스맵 주체 열은 가정치)","owner":"변호사","affects":"process.json actor"}]},"process":{"track":"KR-JSC","version":"0.1","updated":"2026-10-05","source":"한국법인 설립 표준키트 v0.7 프로세스맵 시트","note":"actor(주체)의 지원팀 분장은 가정치. days는 [최소, 최대] 일수이며 null은 확인필요 또는 별도. applies는 inputs.json의 입력·파생 키를 쓰는 조건식이고 'always'는 공통.","actors":{"lawyer":"율촌 담당변호사","legal_support":"법무지원팀","biz_support":"업무지원팀","client":"고객","external":"은행·등기소·세무서 등"},"phases":[{"id":"P0","name":"수임"},{"id":"P1","name":"구조 설계"},{"id":"P2","name":"자료 수집"},{"id":"P3","name":"서류 작성"},{"id":"P4","name":"해외 서명·공증·아포스티유"},{"id":"P5","name":"번역"},{"id":"P6","name":"중국 ODI(고객 측, 병행)","side":"CN"},{"id":"P7","name":"사무실"},{"id":"P8","name":"외국인투자신고"},{"id":"P9","name":"자본금 납입"},{"id":"P10","name":"설립등기"},{"id":"P11","name":"사업자등록"},{"id":"P12","name":"설립 후속"},{"id":"P13","name":"종결"}],"steps":[{"id":"P0-1","task":"이해상충 확인·매터 오픈","actor":["biz_support"],"prereq":[],"output":"매터 번호","days":[1,2],"applies":"always"},{"id":"P0-2","task":"견적·법률서비스계약서 작성","actor":["lawyer"],"prereq":[],"output":"계약서","days":[1,2],"applies":"always"},{"id":"P0-3","task":"계약 체결·착수금 청구·입금 확인","actor":["biz_support"],"prereq":["P0-2"],"output":"청구서, 입금 확인","days":[1,7],"applies":"always"},{"id":"P1-1","task":"킥오프 회의(구조·일정·역할)","actor":["lawyer","client"],"prereq":["P0-3"],"output":"회의록","days":[1,1],"applies":"always"},{"id":"P1-2","task":"출자 주체 확정(본사 직접 / 해외 지주사 / 개인)","actor":["lawyer","client"],"prereq":[],"output":"구조 확정 메모","days":[1,3],"applies":"always"},{"id":"P1-3","task":"중국 ODI 필요 여부·진행 상황 확인","actor":["lawyer","client"],"prereq":["P1-2"],"output":"ODI 일정표","days":[1,1],"applies":"needs_cn_odi","note":"송금 일정의 핵심 변수"},{"id":"P1-4","task":"사업목적 검토(외투 제한·인허가·KSIC)","actor":["lawyer"],"prereq":[],"output":"검토 메모","days":[3,5],"applies":"always","note":"고객이 먼저 작성하고 율촌이 사후 검토(R19)"},{"id":"P1-5","task":"자본금·액면가·임원 구성 결정","actor":["lawyer","client"],"prereq":["P1-4"],"output":"확정 정보","days":[2,3],"applies":"always","note":"10억 원 기준 분기(R07, R08)"},{"id":"P1-6","task":"본점 소재지·사무실 형태 결정","actor":["lawyer","client"],"prereq":[],"output":"주소 확정","days":[3,30],"applies":"always","note":"등록면허세 표와 비상주 비권장 안내(R11, R12)"},{"id":"P1-7","task":"은행 선정·사전 협의","actor":["lawyer"],"prereq":["P1-2"],"output":"은행 담당자 확정","days":[2,5],"applies":"always","note":"고객 선호 은행 확인 후 결정(R20)"},{"id":"P2-1","task":"자료요청서 발송","actor":["lawyer"],"prereq":["P1-1"],"output":"자료요청서","days":[1,1],"applies":"always","note":"이 단계는 스캔본만. 공증 금지 안내(R21)"},{"id":"P2-2","task":"상호 중복 조회(인터넷등기소)","actor":["legal_support"],"prereq":[],"output":"조회 결과","days":[1,1],"applies":"always","note":"한글 상호는 고객 결정(R18)"},{"id":"P2-3","task":"고객 회신 검토·정보 확정","actor":["lawyer"],"prereq":["P2-1"],"output":"확정 정보표","days":[3,7],"applies":"always"},{"id":"P2-4","task":"대표이사 주소 증명 확보","actor":["lawyer","client"],"prereq":["P2-1"],"output":"주소 기재 신분증 또는 주소증명(공증)","days":[1,21],"applies":"always","note":"늦게 알면 공증에 수주 소요(R16)"},{"id":"P2-5","task":"등기 전 비용 지급 방식 확정","actor":["lawyer","client"],"prereq":["P2-1"],"output":"지급 방식 회신","days":[1,7],"applies":"always","note":"등록면허세·임대 계약금·실비(R17)"},{"id":"P3-1","task":"정관 작성(국문 원본 + 번역)","actor":["lawyer"],"prereq":["P2-3"],"output":"정관","days":[3,5],"applies":"always","note":"고객 협의 1~2회 예상"},{"id":"P3-2","task":"해외 서명서류 작성(한/영 병기)","actor":["lawyer"],"prereq":["P2-3"],"output":"위임장·취임승낙서·인감신고서 등","days":[2,2],"applies":"always","note":"임원 수만큼"},{"id":"P3-3","task":"모회사 발급서류 요청","actor":["lawyer"],"prereq":["P1-2"],"output":"요청 목록","days":[1,1],"applies":"is_foreign_company_shareholder","note":"영업집조·이사회결의·권한증명·정관"},{"id":"P3-4","task":"서명·공증 안내서 발송","actor":["lawyer"],"prereq":["P3-2"],"output":"안내서","days":[1,1],"applies":"always","note":"원본 부수·서명 위치·공증 여부 명시"},{"id":"P4-1","task":"고객 서명·날인","actor":["client"],"prereq":["P3-4"],"output":"서명본","days":[3,7],"applies":"always","side":"CN","note":"상장사는 내부 결재 기간 추가"},{"id":"P4-2","task":"현지 공증 + 아포스티유","actor":["client"],"prereq":["P4-1"],"output":"공증·아포스티유본","days":[7,14],"side":"CN","applies":"officers_location == 'abroad' || is_foreign_company_shareholder || shareholder_type == 'foreign_individual'"},{"id":"P4-3","task":"원본 특송·수령·대장 기록","actor":["client","legal_support"],"prereq":["P4-2"],"output":"원본 관리 대장","days":[3,5],"applies":"always","note":"유효기간 3개월 관리"},{"id":"P5-1","task":"외국 발급서류·공증서 한국어 번역(율촌 번역인 확인)","actor":["legal_support"],"prereq":["P4-3"],"output":"번역문","days":[2,3],"applies":"is_foreign_company_shareholder","note":"번역공증 불요(R22). 표준키트의 단계명은 '번역공증'이나 v0.6 이후 번역인 확인 방식으로 확정"},{"id":"P6-1","task":"발전개혁위원회 신고(备案)","actor":["client"],"prereq":[],"output":"备案通知书","days":null,"applies":"needs_cn_odi","side":"CN","status":"needs_check"},{"id":"P6-2","task":"상무주관부문 신고(备案)","actor":["client"],"prereq":[],"output":"企业境外投资证书","days":null,"applies":"needs_cn_odi","side":"CN","status":"needs_check"},{"id":"P6-3","task":"은행 외환등기","actor":["client"],"prereq":["P6-1","P6-2"],"output":"외환등기 증빙","days":null,"applies":"needs_cn_odi","side":"CN","status":"needs_check","note":"완료 전 송금 불가"},{"id":"P7-1","task":"임대차 계약","actor":["client","lawyer"],"prereq":["P1-6","P2-5"],"output":"임대차계약서","days":[3,7],"applies":"always","note":"설립 전에는 법인 명의 불가. 설립 중 법인 사용 특약과 명의변경을 협의. 사업자등록에는 법인 명의 계약 필요"},{"id":"P8-1","task":"외국인투자신고서 작성·제출(외국환은행 또는 KOTRA)","actor":["lawyer","legal_support"],"prereq":["P4-3","P5-1"],"output":"외국인투자신고필증","days":[1,3],"applies":"is_fdi"},{"id":"P9-1","task":"주금 수납 계좌 준비","actor":["legal_support"],"prereq":["P8-1"],"output":"계좌 정보","days":[1,2],"applies":"always"},{"id":"P9-2","task":"해외 송금(투자자 명의 일치)","actor":["client"],"prereq":["P6-3","P9-1"],"output":"송금 확인증","days":[1,3],"applies":"always","note":"등기와 법인계좌 개설 전까지 자본금 사용 불가"},{"id":"P9-3","task":"주금납입보관증명서 또는 잔고증명서 발급","actor":["legal_support"],"prereq":["P9-2"],"output":"증명서","days":[1,2],"applies":"always","note":"10억 원 미만은 잔고증명서 가능(R08)"},{"id":"P10-1","task":"법인인감 제작","actor":["legal_support"],"prereq":["P2-2"],"output":"법인인감","days":[1,1],"applies":"always"},{"id":"P10-2","task":"발기인총회·이사회 의사록, 조사보고서 등 등기서류 작성","actor":["lawyer"],"prereq":["P9-3"],"output":"등기서류 세트","days":[1,2],"applies":"always","note":"이사 수에 따라 이사회 의사록 또는 이사 결정서(R15)"},{"id":"P10-3","task":"등록면허세·지방교육세 납부","actor":["legal_support"],"prereq":["P9-3","P2-5"],"output":"영수증","days":[1,1],"applies":"always","note":"등기 전 납부 필수"},{"id":"P10-4","task":"설립등기 신청","actor":["legal_support"],"prereq":["P10-1","P10-2","P10-3"],"output":"접수증","days":[1,1],"applies":"always"},{"id":"P10-5","task":"등기 완료·등기부등본 발급","actor":["external","legal_support"],"prereq":["P10-4"],"output":"등기부등본","days":[2,5],"applies":"always"},{"id":"P11-1","task":"사업자등록 신청","actor":["legal_support"],"prereq":["P10-5","P7-1"],"output":"사업자등록증","days":[2,7],"applies":"always","note":"현장 확인 가능성"},{"id":"P12-1","task":"외국인투자기업 등록","actor":["lawyer","legal_support"],"prereq":["P9-3","P10-5"],"output":"외국인투자기업 등록증명서","days":null,"deadline":"납입 완료일부터 60일 이내","applies":"is_fdi"},{"id":"P12-2","task":"법인계좌 개설·자본금 전환","actor":["client","legal_support"],"prereq":["P11-1"],"output":"법인계좌","days":[3,5],"applies":"always","note":"실제소유자 서류는 이 단계에서 요청"},{"id":"P12-3","task":"D-8 비자","actor":["client","external"],"prereq":["P12-1"],"output":"비자","days":null,"applies":"d8_needed","status":"needs_check","note":"독립 사무실 필요(R14)"},{"id":"P13-1","task":"결과물 송부·설립 완료 안내","actor":["lawyer"],"prereq":["P11-1","P12-2"],"output":"완료 보고서","days":[1,1],"applies":"always"},{"id":"P13-2","task":"잔금 청구·실비 정산","actor":["biz_support"],"prereq":["P10-5"],"output":"청구서","days":[1,7],"applies":"always"},{"id":"P13-3","task":"교훈 기록·규칙 데이터 반영","actor":["lawyer"],"prereq":[],"output":"규칙 데이터 업데이트","days":[1,1],"applies":"always"}]},"documents":{"track":"KR-JSC","version":"0.1","updated":"2026-10-05","source":"한국법인 설립 표준키트 v0.7 공증·번역 시트","principles":[{"id":"PR1","text":"공증 대상은 율촌이 작성한 서명서류(A1~A6)와 조건부 주소증명(B1)뿐. 중국 법인 서류는 스캔본·사본으로 받는다.","basis":"법무지원팀 최종확인(2026-09-28)"},{"id":"PR2","text":"아포스티유는 공증서에 부착·합철한다(분리 금지). 중국은 2023.11.7. 아포스티유 협약 발효로 영사확인 불요."},{"id":"PR3","text":"번역은 한국에서 율촌이 1회: 번역인 성명·주소·서명. 중국 측 번역과 한국 번역공증은 불요.","basis":"상업등기선례 제1-22호"},{"id":"PR4","text":"한/영 병기 율촌 양식은 번역 불요. 공증서·아포스티유 문구(중문)는 율촌이 번역문을 첨부."},{"id":"PR5","text":"첫 자료요청서 단계는 스캔본만. 공증은 서명·공증 안내서 발송 후 한 번에. 유효기간 3개월 관리."}],"submit_to_labels":{"bank":"은행","registry":"등기소","registry_reference":"등기 참고","cn_notary":"중국 공증처","cn_odi":"중국 ODI"},"groups":{"A":"서명 문서(율촌 작성, 한/영 병기)","B":"조건부 공증 서류","C":"스캔본·사본으로 충분한 서류","D":"한국에서 율촌이 작성"},"documents":[{"id":"A1","group":"A","name":"주주 위임장(특별수권위임장, SPOA)","signer":"주주의 법정대표인 서명 + 회사 공장(公章)","originals":3,"originals_use":"은행 1 / 등기 1 / 예비 1","notarize":true,"apostille":true,"translation":"불요(병기). 공증서만 율촌 번역","submit_to":["bank","registry"],"applies":"always","status":"needs_check","note":"원본 부수는 선례 A에서 2부였음. 은행 제출 후 등기용이 남는지 확인 중(Q-G)"},{"id":"A2","group":"A","name":"대표이사 취임승낙서","signer":"대표이사","originals":1,"notarize":true,"notarize_note":"여권·신분증 사본을 합철","apostille":true,"translation":"불요(병기)","submit_to":["registry"],"applies":"always","status":"confirmed","basis":"인베스트코리아 FAQ 16, 선례 A","note":"이사 1인 회사는 직함이 'Director'(R15)"},{"id":"A3","group":"A","name":"대표이사 인감신고서(서명 신고)","signer":"대표이사","originals":1,"notarize":true,"notarize_note":"서명공증","apostille":true,"translation":"불요(병기)","submit_to":["registry"],"applies":"always","status":"confirmed","basis":"인베스트코리아 FAQ 17"},{"id":"A4","group":"A","name":"대표이사 위임장","signer":"대표이사","originals":1,"notarize":true,"apostille":true,"translation":"불요(병기)","submit_to":["registry"],"applies":"always","status":"confirmed","basis":"인베스트코리아 FAQ 22, 선례 A"},{"id":"A5","group":"A","name":"이사 취임승낙서(여권 사본 첨부)·위임장(있는 경우)","signer":"각 이사","originals":1,"per":"director","notarize":true,"apostille":true,"translation":"불요(병기)","submit_to":["registry"],"applies":"director_count != '1'","status":"confirmed"},{"id":"A6","group":"A","name":"감사 취임승낙서(여권 사본 첨부)·위임장(있는 경우)","signer":"감사","originals":1,"notarize":true,"apostille":true,"translation":"불요(병기)","submit_to":["registry"],"applies":"has_auditor == true","status":"confirmed"},{"id":"B1","group":"B","name":"대표이사 주소증명","signer":"본인 또는 현지 기관 발급","originals":1,"notarize":true,"apostille":true,"translation":"율촌 번역","submit_to":["registry"],"applies":"rep_director_residence == 'other_or_no_address'","status":"confirmed","basis":"R16","note":"중국 대륙 거주자는 거민신분증 앞뒤면 사본으로 갈음. 고객 안내서에는 임원 정보 아래 안내문으로만 기재"},{"id":"C1","group":"C","name":"영업집조(营业执照)","issuer":"출자 법인","form":"스캔본","notarize":false,"apostille":false,"translation":"필요시 율촌","submit_to":["bank","registry_reference"],"use":"은행 외국인투자신고의 국적 증명, 등기 참고","applies":"shareholder_type == 'cn_company_direct'","status":"confirmed","basis":"법무지원팀 확인(2026-09-28). 이전 버전의 공증+아포스티유 요구는 삭제"},{"id":"C2","group":"C","name":"주주명부·실제소유자 정보(상장사는 연보)","issuer":"출자 법인","form":"스캔본","notarize":false,"apostille":false,"translation":"필요시 율촌","submit_to":["bank"],"use":"은행 KYC","applies":"is_foreign_company_shareholder","status":"confirmed","note":"실제소유자 서류는 법인계좌 개설 단계(P12-2)에서 요청"},{"id":"C3","group":"C","name":"세무번호(납세자번호) 증명서류","issuer":"출자 법인","form":"스캔본","notarize":false,"apostille":false,"translation":"필요시 율촌","submit_to":["bank"],"use":"은행 KYC(TIN)","applies":"is_foreign_company_shareholder","status":"confirmed","basis":"법무지원팀 추가(2026-09-28), 선례 A","note":"중국 법인은 统一社会信用代码"},{"id":"C4","group":"C","name":"법정대표인 여권","issuer":"출자 법인","form":"스캔본","notarize":false,"apostille":false,"translation":"불요","submit_to":["bank"],"use":"은행 KYC","applies":"is_foreign_company_shareholder","status":"confirmed"},{"id":"C5","group":"C","name":"법정대표인 신분증명서","issuer":"출자 법인","form":"중국 공증처 제출용","notarize":false,"apostille":false,"translation":"해당 없음","submit_to":["cn_notary"],"use":"공증처의 서명 권한 확인","applies":"shareholder_type == 'cn_company_direct'","status":"confirmed","note":"한국으로 보낼 필요 없음"},{"id":"C6","group":"C","name":"이사회결의(모회사)","issuer":"출자 법인","form":"사본","notarize":false,"apostille":false,"translation":"필요시 율촌","submit_to":["cn_odi"],"use":"중국 ODI","applies":"shareholder_type == 'cn_company_direct'","status":"needs_check","note":"한국 기관이 제출을 요구하는지 확인필요(Q-G)"},{"id":"C7","group":"C","name":"정관(모회사)","issuer":"출자 법인","form":"사본(필요시)","notarize":false,"apostille":false,"translation":"필요시 율촌","submit_to":["bank"],"use":"은행 KYC 참고","applies":"is_foreign_company_shareholder","status":"confirmed"},{"id":"D1","group":"D","name":"번역문(주소증명, 공증서·아포스티유, 필요시 C 서류)","signer":"율촌 번역인(성명·주소·서명)","originals":1,"per":"document","notarize":false,"apostille":false,"submit_to":["registry"],"applies":"always","status":"confirmed","basis":"상업등기선례 제1-22호"}],"not_yet_migrated":["주주 유형이 해외 지주사·조세회피지 법인·외국 개인일 때의 서류(해당국 등록증명, 재직증명, 주주 여권 등)는 rules.json의 documents_extra에 문장으로만 있음. 선례 A·B·D 자료를 대조해 이 파일에 행으로 추가해야 함","한국 측 등기서류 세트(정관, 발기인총회 의사록, 이사회 의사록 또는 이사 결정서, 조사보고서, 주식인수증 등)와 사업자등록·외국인투자신고 서식은 템플릿 폴더 대조 후 추가"]},"agencies":{"track":"KR-JSC","version":"0.1","updated":"2026-10-05","source":"한국법인 설립 표준키트 v0.7 (용어집, 프로세스맵, 공증·번역 시트)","note":"client_text는 고객 안내서에 쓰는 쉬운 설명의 국문 원안. 중문·영문은 common/i18n에서 관리. 창구 위치·접수 방법 등 세부는 사건별로 달라 아직 넣지 않았다.","agencies":[{"id":"cn_notary","side":"CN","name":"중국 공증처(公证处)","role":"서명서류(A1~A6) 공증","who_goes":"고객(서명자 본인 또는 회사 담당자)","steps":["P4-2"],"client_text":"율촌이 보낸 서명서류에 서명한 뒤, 거주지 또는 회사 소재지 공증처에서 공증을 받습니다. 법정대표인 신분증명서는 공증처가 서명 권한을 확인하는 데 쓰이며 한국으로 보낼 필요가 없습니다.","status":"needs_check","open":"공증처가 한/영 병기 서류를 중문 번역 없이 공증하는지 사전 확인(Q-N). 요구하면 율촌이 중문 참고번역 제공"},{"id":"cn_apostille","side":"CN","name":"아포스티유 발급기관","role":"공증서에 아포스티유(附加证明书) 부착","who_goes":"고객 또는 공증처 대행","steps":["P4-2"],"client_text":"공증서에 아포스티유를 받습니다. 아포스티유는 공증서와 합철된 상태로 보내야 하며 분리하면 안 됩니다. 영사확인은 필요 없습니다.","status":"needs_check","open":"지역별 발급 창구와 소요기간은 표준키트에 없음. 선례 C 진행 결과로 채운다"},{"id":"cn_odi","side":"CN","name":"발전개혁위원회·상무주관부문·은행(ODI)","role":"중국 법인이 직접 출자할 때 경외투자 신고와 외환등기","who_goes":"고객(중국 본사)","steps":["P6-1","P6-2","P6-3"],"client_text":"중국 본사가 직접 출자하는 경우 송금 전에 발전개혁위원회 신고, 상무주관부문 신고, 은행 외환등기를 마쳐야 합니다. 완료 전에는 자본금을 송금할 수 없습니다.","status":"needs_check","open":"소요기간(Q-O)"},{"id":"bank","side":"KR","name":"외국환은행","role":"외국인투자신고 접수, 주금 수납, 주금납입보관증명서·잔고증명서 발급, 법인계좌 개설, KYC","who_goes":"율촌(법무지원팀). 법인계좌 개설은 고객 협조 필요","steps":["P1-7","P8-1","P9-1","P9-3","P12-2"],"client_text":"율촌이 은행과 협의해 외국인투자신고와 자본금 수납 계좌를 준비합니다. 자본금은 투자자 명의로 송금해야 하며, 등기와 법인계좌 개설이 끝나기 전에는 사용할 수 없습니다.","status":"confirmed"},{"id":"kotra","side":"KR","name":"KOTRA(인베스트코리아)","role":"외국인투자신고 접수(은행 대신 가능), 외국인투자기업 등록","who_goes":"율촌","steps":["P8-1","P12-1"],"client_text":"외국인투자신고는 외국환은행 또는 KOTRA에 합니다. 율촌이 대리합니다.","status":"confirmed","open":"외국인투자기업 등록 접수처(은행 또는 KOTRA)는 신고한 곳에 따라 달라질 수 있어 사건별 확인"},{"id":"registry","side":"KR","name":"관할 등기소","role":"상호 중복 조회(인터넷등기소), 설립등기, 등기부등본·법인인감증명 발급","who_goes":"율촌(법무지원팀)","steps":["P2-2","P10-4","P10-5"],"client_text":"율촌이 설립등기를 신청합니다. 통상 신청 후 2~5일 안에 완료됩니다.","status":"confirmed","open":"등기신청 대리권 서류(Q-A)"},{"id":"local_tax","side":"KR","name":"본점 소재지 지방자치단체(등록면허세)","role":"등록면허세·지방교육세 납부","who_goes":"율촌(법무지원팀)","steps":["P10-3"],"client_text":"등기 신청 전에 등록면허세와 지방교육세를 내야 합니다. 이 시점에는 자본금을 쓸 수 없으므로 지급 방식을 미리 정합니다.","status":"confirmed"},{"id":"tax_office","side":"KR","name":"관할 세무서","role":"사업자등록","who_goes":"율촌(법무지원팀)","steps":["P11-1"],"client_text":"등기 후 세무서에 사업자등록을 합니다. 법인 명의 임대차계약서가 필요하고 사무실 현장 확인이 있을 수 있습니다.","status":"confirmed","open":"대표이사가 비거주 외국인일 때 방한 또는 납세관리인 지정 요구 여부(Q-E), 비상주 사무실 가능 여부(Q-D)"},{"id":"immigration","side":"KR","name":"출입국·외국인관서","role":"D-8 비자","who_goes":"고객 또는 별도 대행","steps":["P12-3"],"client_text":"파견 임원이 D-8 비자가 필요한 경우 외국인투자기업 등록 후 신청합니다. 독립 사무실이 필요합니다.","status":"needs_check"}]},"costs":{"track":"KR-JSC","version":"0.2","updated":"2026-10-05","source":"한국법인 설립 표준키트 v0.7 (용어집 등록면허세·지방교육세, R11, R17). 중국 측 실비 수치는 선례 C 자료요청서(2026-09-28)","categories":{"fee":"율촌 보수(사건마다 직접 입력)","tax":"세금·공과금(자동 계산)","expense":"실비(예상 범위. 선례가 쌓이면 갱신)"},"items":[{"id":"FEE-1","category":"fee","name":"율촌 보수: 착수금","input":"manual","currency":"manual","when":"계약 체결 후(P0-3)"},{"id":"FEE-2","category":"fee","name":"율촌 보수: 잔금","input":"manual","currency":"manual","when":"등기 완료 후(P13-2)"},{"id":"TAX-1","category":"tax","name":"등록면허세","formula":"capital_krw * 0.004 * (head_office_zone == 'overcrowding' ? 3 : 1)","currency":"KRW","when":"등기 신청 전 납부(P10-3)","status":"confirmed","basis":"자본금의 0.4%. 과밀억제권역(산업단지 제외)은 3배 중과: 지방세법 제28조 제2항","note":"중과 제외 업종(시행령 제26조)에 해당하면 3배를 적용하지 않음. 프로그램은 업종 예외를 자동 판단하지 않고 안내문으로 표시"},{"id":"TAX-1-MIN","category":"tax","name":"등록면허세 최저세액","status":"needs_check","note":"표준키트에 없는 항목. 금액과 중과 시 적용 방식은 법령 확인 후 넣는다. 확인 전에는 계산에 반영하지 않는다."},{"id":"TAX-2","category":"tax","name":"지방교육세","formula":"TAX-1 * 0.2","currency":"KRW","when":"등록면허세와 함께 납부(P10-3)","status":"confirmed","basis":"등록면허세의 20%"},{"id":"EXP-1","category":"expense","name":"현지 공증료","paid_by_default":"client","range_text":"건당 수백 위안 수준(공증처 요금 기준)","currency":"CNY","status":"rough","basis":"선례 C 자료요청서의 고객 안내 문구","region":"CN"},{"id":"EXP-2","category":"expense","name":"아포스티유 수수료","paid_by_default":"client","range_text":"부당 약 100위안(긴급 시 별도)","currency":"CNY","status":"rough","basis":"선례 C 자료요청서의 고객 안내 문구","region":"CN"},{"id":"EXP-3","category":"expense","name":"원본 국제 특송","paid_by_default":"client","range_text":null,"status":"needs_data"},{"id":"EXP-4","category":"expense","name":"법인인감 제작","paid_by_default":"yulchon_advance","range_text":null,"status":"needs_data"},{"id":"EXP-5","category":"expense","name":"등기 신청 수수료·증명서 발급비","paid_by_default":"yulchon_advance","range_text":null,"status":"needs_data"},{"id":"EXP-6","category":"expense","name":"임대 계약금·보증금·임대료","paid_by_default":"client","range_text":null,"status":"needs_data","note":"등기 전에는 자본금을 쓸 수 없으므로 지급 방식을 미리 정함(R17). 일반 임대는 보증금·월세·관리비·중개수수료, 공유오피스 독립실은 예치금(보통 1~2개월분)과 월 이용료"},{"id":"EXP-7","category":"expense","name":"번역 비용","paid_by_default":"included_or_manual","range_text":null,"status":"needs_data","note":"율촌 번역이 보수에 포함되는지 사건별로 입력"}],"examples":[{"capital_krw":100000000,"zone":"other","registration_tax":400000,"education_tax":80000,"total":480000},{"capital_krw":100000000,"zone":"overcrowding","registration_tax":1200000,"education_tax":240000,"total":1440000},{"capital_krw":1000000000,"zone":"overcrowding","registration_tax":12000000,"education_tax":2400000,"total":14400000}],"tracking_fields":["estimated","actual","paid_by","billed","received","memo"],"paid_by_values":{"yulchon_advance":"율촌 대납(소액만)","client":"고객 직접 지급","client_remit":"고객 선송금분에서 지급","korean_affiliate":"한국 관계사 지급","included_or_manual":"보수 포함 여부를 사건별로 입력"},"decisions":["2026-10-05: 공증·아포스티유 소요기간(7~14일)과 중문 번역 주체(율촌이 참고번역 제공)는 표준키트 기준을 유지한다. 선례 C 자료요청서의 3~5주, 고객 번역기관 의뢰 문구는 데이터에 반영하지 않는다."],"notes":["5년 내 증자와 과밀억제권역 밖에서 5년 내 전입도 중과 대상(R11). 설립 시점 계산에는 반영하지 않고 고객 안내문에 기재","status rough: 고객 안내용 대략치. 실제 지출 자료로 검증되지 않음"]}}}};
